  for (let i = n; i >= 1; i--) { const u = i / n, y = yb - h + h * 0.82 * u, w = h * (0.05 + 0.09 * u); g.lineTo(x - w * 0.45, y - h * 0.02); g.lineTo(x - w, y); }
