  if (gw < 0.98) { ctx.fillStyle = "rgba(141,135,124,0.85)"; for (let i = 0; i < 46; i++) { const x = cx0 + 30 + rnd(i) * (side - 60), y = ((rnd(i * 3) * 600 + t * 520) % 600) - 300 + top - 300; if (y < top) ctx.fillRect(x, y, 6, 14); } }
